    10	import java.time.LocalDate;
    11	import java.time.Month;
    12	
    13	/**
    14	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    15	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    16	 * (half-even) at every step.
    17	 */
    18	public final class PriceCalculator {
    19	
    20	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    21	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    22	
    23	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    24	        int nights = 0;
    25	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    26	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    27	            subtotal = subtotal.add(nightPrice(room, night));
    28	            nights++;
    29	        }
    30	        BigDecimal discount = switch (ratePlan) {
    31	            case STANDARD -> cents(BigDecimal.ZERO);
    32	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    33	        };
    34	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    35	    }
    36	
    37	    BigDecimal nightPrice(Room room, LocalDate night) {
    38	        BigDecimal nightlyRate = room.nightlyRate();
    39	        if (isHighSeason(night)) {
    40	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    41	        }
    42	        return cents(nightlyRate);
    43	    }
    44	
    45	    /** High season: from December 15 to the end of February, and the whole of July. */
    46	    static boolean isHighSeason(LocalDate date) {
    47	        Month month = date.getMonth();
    48	        return month == Month.JANUARY
    49	                || month == Month.FEBRUARY
    50	                || month == Month.JULY
    51	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    52	    }
    53	
    54	    static BigDecimal cents(BigDecimal value) {
    55	        return value.setScale(2, RoundingMode.HALF_EVEN);
    56	    }
    57	}
